from dataclasses import dataclass
from pathlib import Path


@dataclass(frozen=True)
class Trial:
    task: str
    reward: int


def read_trials(path: Path) -> list[Trial]:
    trials = []
    for line in path.read_text().splitlines():
        task, reward = line.split()
        trials.append(Trial(task=task, reward=int(reward)))
    return trials


def pass_rate(trials: list[Trial]) -> float:
    return sum(t.reward for t in trials) / len(trials)


trials = read_trials(Path("trials.txt"))
print(trials[0])
print(f"pass rate: {pass_rate(trials):.0%}")
